const job = $json || {};

const clean = (value) =>
  String(value ?? '')
    .replace(/\s+/g, ' ')
    .trim();

const requested = Math.max(
  1,
  Math.min(200, Number(job.requested_leads || 1))
);

const searchLimit = Math.min(
  300,
  Math.max(requested, Math.ceil(requested * 1.5))
);

// Build location and remove duplicate parts such as:
// Dallas, Texas, United States, United States
const rawLocation = clean(job.location);

const locationValues = rawLocation
  ? [rawLocation, job.country]
  : [job.city, job.region, job.country];

const seenLocationParts = new Set();

const locationParts = locationValues
  .flatMap((value) => clean(value).split(','))
  .map((value) => clean(value))
  .filter(Boolean)
  .filter((value) => {
    const normalized = value.toLowerCase();

    if (seenLocationParts.has(normalized)) {
      return false;
    }

    seenLocationParts.add(normalized);
    return true;
  });

const locationQuery = locationParts.join(', ');

const attemptCount = Number(job.attempt_count || 0) + 1;
const workerId = `00B-${$execution.id}`;

return {
  json: {
    ...job,
    worker_id: workerId,
    attempt_count_next: attemptCount,
    claim_started_at: new Date().toISOString(),
    location_query: locationQuery,

    apify_input: {
      searchStringsArray: [clean(job.category)],
      locationQuery,
      maxCrawledPlacesPerSearch: searchLimit,
      language: clean(job.language || 'en').toLowerCase(),
      searchMatching: 'all',
      website: 'allPlaces',
      skipClosedPlaces: true,
      scrapePlaceDetailPage: false,
      scrapeContacts: true,

      scrapeSocialMediaProfiles: {
        facebooks: false,
        instagrams: false,
        youtubes: false,
        tiktoks: false,
        twitters: false
      },

      maximumLeadsEnrichmentRecords: 0,
      verifyLeadsEnrichmentEmails: false,
      maxReviews: 0,
      scrapeReviewsPersonalData: false,
      maxImages: 0,
      scrapeImageAuthors: false,
      includeWebResults: false,
      scrapeDirectories: false,
      enableCompetitorAnalysis: false,
      maxCompetitorsToAnalyze: 0
    }
  }
};

const original = $('Prepare Apify Actor Start').first().json;
const updated = $json || {};
const message = [
  updated.error?.message,
  updated.error?.description,
  updated.errorMessage,
  updated.message,
  updated.description
].filter(Boolean).join(' | ');
const hasError = Boolean(
  updated.error ||
  updated.errorMessage ||
  (updated.httpCode && Number(updated.httpCode) >= 400) ||
  (updated.code && String(updated.code).toLowerCase().startsWith('pgrst'))
);
const claimSucceeded = !hasError && Boolean(updated.id && updated.job_id);
return {
  json: {
    ...original,
    ...(claimSucceeded ? updated : {}),
    claim_succeeded: claimSucceeded,
    claim_error: hasError ? message.slice(0, 1500) : (claimSucceeded ? '' : 'Job was already claimed by another execution.')
  }
};

const job = $('Resolve Job Claim').first().json;
const response = $json || {};
const body = response.body ?? response;
const data = body?.data ?? body;
const httpStatus = Number(response.statusCode || response.status || 0);
const message = [
  body?.error?.message,
  body?.error?.type,
  response.error?.message,
  response.errorMessage,
  response.message
].filter(Boolean).join(' | ');
const started = Boolean(data && data.id && data.defaultDatasetId) && (!httpStatus || (httpStatus >= 200 && httpStatus < 300));
return {
  json: {
    ...job,
    actor_started: started,
    apify_run_id: started ? String(data.id) : '',
    apify_dataset_id: started ? String(data.defaultDatasetId) : '',
    apify_status: started ? String(data.status || 'READY') : 'START_FAILED',
    actor_started_at: started ? String(data.startedAt || new Date().toISOString()) : '',
    actor_start_error: started ? '' : (message || `Apify Actor start failed with HTTP ${httpStatus || 'unknown'}`).slice(0, 1500)
  }
};

const job = $json || {};
return {
  json: {
    job_id: job.job_id,
    event_type: 'apify_run_started',
    status: job.status || 'collecting',
    stage: job.current_stage || 'google_maps_collecting',
    severity: 'info',
    error_code: '',
    event_message: 'Apify Google Maps Actor started successfully.',
    event_payload: {
      apify_run_id: job.apify_run_id,
      apify_dataset_id: job.apify_dataset_id,
      attempt_count: job.attempt_count
    }
  }
};

const input = $json || {};
const attempts = Number(input.attempt_count || input.attempt_count_next || 1);
const maxAttempts = Number(input.max_attempts || 3);
const willRetry = attempts < maxAttempts;
const delayMinutes = attempts <= 1 ? 1 : (attempts === 2 ? 5 : 15);
const nextAttempt = new Date(Date.now() + delayMinutes * 60000).toISOString();
const actorStatus = String(input.apify_status || '').toUpperCase();
const errorCode = input.actor_start_error
  ? 'APIFY_START_FAILED'
  : (actorStatus ? `APIFY_RUN_${actorStatus.replace(/[^A-Z0-9]+/g, '_')}` : 'APIFY_RUN_FAILED');
const errorMessage = String(
  input.actor_start_error ||
  input.apify_error ||
  input.poll_error ||
  `Apify Actor ended with status ${actorStatus || 'unknown'}.`
).slice(0, 1500);
return {
  json: {
    ...input,
    retry_status: willRetry ? 'queued' : 'failed',
    retry_stage: willRetry ? 'retry_scheduled' : 'google_maps_collection_failed',
    next_attempt_at: willRetry ? nextAttempt : null,
    error_code: errorCode,
    error_message: errorMessage,
    retry_event_type: willRetry ? 'job_retry_scheduled' : 'job_failed',
    retry_severity: willRetry ? 'warning' : 'error',
    retry_message: willRetry
      ? `Attempt ${attempts} failed. Retry scheduled in ${delayMinutes} minute(s).`
      : `Lead discovery failed after ${attempts} attempt(s).`
  }
};

const job = $json || {};
return {
  json: {
    job_id: job.job_id,
    event_type: job.status === 'failed' ? 'job_failed' : 'job_retry_scheduled',
    status: job.status,
    stage: job.current_stage,
    severity: job.status === 'failed' ? 'error' : 'warning',
    error_code: job.error_code || 'APIFY_RUN_FAILED',
    event_message: job.error_message || 'Apify run failed.',
    event_payload: {
      attempt_count: job.attempt_count,
      max_attempts: job.max_attempts,
      next_attempt_at: job.next_attempt_at,
      apify_status: job.apify_status
    }
  }
};

const job = $json || {};
return {
  json: {
    ...job,
    poll_requested_at: new Date().toISOString(),
    collection_poll_worker_id: String(job.locked_by || ('00B-poll-' + $execution.id)),
    poll_url: `https://api.apify.com/v2/actor-runs/${encodeURIComponent(String(job.apify_run_id || 'missing'))}`
  }
};

const job = $('Prepare Actor Poll').first().json;
const response = $json || {};
const body = response.body ?? response;
const data = body?.data ?? body;
const httpStatus = Number(response.statusCode || response.status || 0);
const apiError = Boolean(
  response.error ||
  response.errorMessage ||
  (httpStatus && (httpStatus < 200 || httpStatus >= 300)) ||
  !data ||
  !data.status
);
const status = String(data?.status || 'UNKNOWN').toUpperCase();
const terminalFailures = new Set(['FAILED', 'TIMED-OUT', 'ABORTED']);
let runState = 'running';
if (apiError) runState = 'poll_error';
else if (status === 'SUCCEEDED') runState = 'succeeded';
else if (terminalFailures.has(status)) runState = 'terminal_failure';
const message = [
  body?.error?.message,
  body?.error?.type,
  response.error?.message,
  response.errorMessage,
  data?.statusMessage,
  response.message
].filter(Boolean).join(' | ');
return {
  json: {
    ...job,
    apify_status: status,
    apify_dataset_id: String(data?.defaultDatasetId || job.apify_dataset_id || ''),
    apify_finished_at: data?.finishedAt || null,
    run_state: runState,
    poll_error: apiError ? (message || `Apify poll failed with HTTP ${httpStatus || 'unknown'}`).slice(0, 1500) : '',
    apify_error: terminalFailures.has(status) ? (message || `Apify run ended with status ${status}`).slice(0, 1500) : ''
  }
};

const job = $('Parse Apify Run Status').first().json;
const response = $json || {};
const body = response.body ?? response;
let items = [];
if (Array.isArray(body)) items = body;
else if (Array.isArray(body?.data)) items = body.data;
else if (Array.isArray(response.data)) items = response.data;
const httpStatus = Number(response.statusCode || response.status || 0);
const message = [
  body?.error?.message,
  response.error?.message,
  response.errorMessage,
  response.message
].filter(Boolean).join(' | ');
const fetchOk = (!httpStatus || (httpStatus >= 200 && httpStatus < 300)) && Array.isArray(items);
return {
  json: {
    ...job,
    dataset_fetch_ok: fetchOk,
    dataset_items: fetchOk ? items : [],
    dataset_fetch_error: fetchOk ? '' : (message || `Dataset fetch failed with HTTP ${httpStatus || 'unknown'}`).slice(0, 1500)
  }
};

const context = $input.first()?.json || {};
const rows = Array.isArray(context.dataset_items) ? context.dataset_items : [];
const clean = (value, max = 1000) => String(value ?? '').replace(/\s+/g, ' ').trim().slice(0, max);
// No URL global dependency: compatible with n8n Code-node sandboxes.
const normalizeWebsite = (value) => {
  if (Array.isArray(value)) {
    for (const item of value) { const result = normalizeWebsite(item); if (result.website) return result; }
    return { website: '', domain: '' };
  }
  if (value && typeof value === 'object') return normalizeWebsite(value.url || value.uri || value.website || value.value || '');
  let raw = String(value ?? '').trim().replace(/&amp;/gi, '&');
  if (!raw || /[\s\\<>"'`]/.test(raw)) return { website: '', domain: '' };
  if (/^[a-z][a-z0-9+.-]*:/i.test(raw) && !/^https?:\/\//i.test(raw)) return { website: '', domain: '' };
  if (raw.startsWith('//')) raw = 'https:' + raw;
  const candidate = /^https?:\/\//i.test(raw) ? raw : 'https://' + raw;
  const match = candidate.match(/^(https?):\/\/([^/?#:]+)(?::(\d{1,5}))?([/?#].*)?$/i);
  if (!match || match[2].includes('@')) return { website: '', domain: '' };
  const host = match[2].toLowerCase().replace(/\.$/, '');
  if (host.length > 253 || !/^(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/i.test(host)) return { website: '', domain: '' };
  if (match[3] && !['80', '443'].includes(match[3])) return { website: '', domain: '' };
  const domain = host.replace(/^www\./, '');
  const blockedSites = ['google.com', 'google.co.uk', 'maps.app.goo.gl', 'goo.gl', 'g.page', 'googleusercontent.com', 'facebook.com', 'fb.com', 'instagram.com', 'linkedin.com', 'yelp.com', 'youtube.com', 'tiktok.com', 'twitter.com', 'x.com', 'yellowpages.com', 'mapquest.com', 'tripadvisor.com', 'bbb.org', 'chamberofcommerce.com', 'manta.com', 'angi.com', 'thumbtack.com', 'healthgrades.com', 'zocdoc.com', 'webmd.com', 'gmail.com', 'outlook.com', 'yahoo.com', 'hotmail.com'];
  if (blockedSites.some(site => domain === site || domain.endsWith('.' + site))) return { website: '', domain: '' };
  let suffix = (match[4] || '/').split('#')[0] || '/';
  if (suffix.startsWith('?')) suffix = '/' + suffix;
  return { website: match[1].toLowerCase() + '://' + host + (match[3] ? ':' + match[3] : '') + suffix, domain };
};
const websiteFromPlace = row => {
  for (const value of [row.website, row.websiteUri, row.websiteUrl, row.website_url, row.webSite, row.websites, row.websiteDetails]) {
    const result = normalizeWebsite(value);
    if (result.website) return result;
  }
  return { website: '', domain: '' };
};
const routeWebsiteService = (requested, website) => {
  const service = String(requested || 'Website Redesign').trim();
  const websiteServices = ['Website Redesign', 'New Website', 'Web Development', 'SEO Improvement', 'Performance Optimization'];
  if (!websiteServices.includes(service)) return service;
  if (!website) return 'New Website';
  return ['New Website', 'Web Development'].includes(service) ? 'Website Redesign' : service;
};

const extractEmail = (row) => {
  const candidates = [];
  const add = (value) => {
    if (Array.isArray(value)) return value.forEach(add);
    if (value && typeof value === 'object') return add(value.email ?? value.address ?? value.value);
    const text = clean(value, 500).toLowerCase();
    const matches = text.match(/[a-z0-9.!#$%&'*+/=?^_\`{|}~-]+@[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)+/gi) || [];
    candidates.push(...matches);
  };
  add(row.email);
  add(row.emails);
  add(row.contactEmails);
  return [...new Set(candidates)].find((email) => email.length <= 254) || '';
};
const normalizePhone = (value) => {
  const raw = clean(value, 80);
  if (!raw) return '';
  let candidate = raw.replace(/[^0-9+]/g, '');
  if (candidate.startsWith('00')) candidate = '+' + candidate.slice(2);
  const digits = candidate.replace(/\D/g, '');
  return digits.length >= 7 && digits.length <= 15 ? candidate : '';
};
const keyPart = (value) => clean(value, 300).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
const contactQuality = (row) => {
  const website = websiteFromPlace(row || {}).website;
  const email = extractEmail(row || {});
  const phone = normalizePhone(row?.phoneUnformatted || row?.phone || (Array.isArray(row?.phones) ? row.phones[0] : row?.phones));
  const rating = Number(row?.totalScore || row?.rating || 0) || 0;
  const reviews = Number(row?.reviewsCount || row?.userRatingCount || 0) || 0;
  return (email ? 400000 : 0) + (website ? 800000 : 0) + (phone ? 200000 : 0) + Math.round(rating * 1000) + Math.min(reviews, 999);
};
const seen = new Set();
const output = [];
let rejected = 0;
let internalDuplicates = 0;
const requested = Math.max(1, Number(context.requested_leads || 1));
const orderedRows = [...rows].sort((a, b) => contactQuality(b) - contactQuality(a));

for (const row of orderedRows) {
  if (output.length >= requested) break;
  if (!row || typeof row !== 'object') {
    rejected++;
    continue;
  }

  const companyName = clean(row.title || row.name, 300);
  if (!companyName) {
    rejected++;
    continue;
  }

  const placeId = clean(row.placeId || row.place_id || row.cid || row.fid, 300);
  const normalizedWebsite = websiteFromPlace(row);
  const email = extractEmail(row);
  const phone = normalizePhone(row.phoneUnformatted || row.phone || (Array.isArray(row.phones) ? row.phones[0] : row.phones));
  const address = clean(row.address || row.formattedAddress, 600);
  const city = clean(row.city || context.location, 150);
  const category = clean(row.categoryName || (Array.isArray(row.categories) ? row.categories[0] : '') || context.category, 150);
  const sourceUrl = clean(row.url || row.googleMapsUri || row.searchPageUrl, 2000);
  const canonicalLeadKey = placeId
    ? 'place:' + placeId
    : (normalizedWebsite.domain
      ? 'domain:' + normalizedWebsite.domain
      : (phone ? 'phone:' + phone.replace(/\D/g, '') : 'business:' + keyPart(companyName) + '|' + keyPart(address)));

  if (seen.has(canonicalLeadKey)) {
    internalDuplicates++;
    continue;
  }
  seen.add(canonicalLeadKey);

  const needSignal = normalizedWebsite.website
    ? 'Public Google Maps business available for human website review'
    : 'No official website listed in this result; public website search and human review pending';

  output.push({
    json: {
      candidate_present: true,
      job_id: context.job_id,
      collection_poll_worker_id: context.collection_poll_worker_id,
      lead_key: canonicalLeadKey,
      company_name: companyName,
      website: normalizedWebsite.website,
      domain: normalizedWebsite.domain,
      contact_name: '',
      job_title: '',
      email,
      phone,
      country: clean(context.country || row.countryCode, 100),
      city,
      industry: category,
      source: 'google_maps_apify',
      source_url: sourceUrl,
      source_place_id: placeId,
      need_signal: needSignal,
      service_interest: routeWebsiteService(context.service_interest, normalizedWebsite.website),
      address,
      rating: Number(row.totalScore || row.rating || 0) || 0,
      review_count: Number(row.reviewsCount || row.userRatingCount || 0) || 0,
      is_recommended: false,
      recommendation_rank: null,
      raw_payload: {
        title: companyName,
        category,
        address,
        city,
        state: clean(row.state, 100),
        countryCode: clean(row.countryCode, 10),
        website: normalizedWebsite.website,
        source_website: clean(typeof row.website === 'string' ? row.website : row.websiteUri || row.websiteUrl || '', 2000),
        requested_service: clean(context.service_interest || 'Website Redesign', 150),
        human_review_only: true,
        phone,
        email,
        placeId,
        rating: Number(row.totalScore || row.rating || 0) || 0,
        reviewsCount: Number(row.reviewsCount || row.userRatingCount || 0) || 0,
        url: sourceUrl,
        businessStatus: clean(row.businessStatus || row.status, 100),
        permanentlyClosed: row.permanentlyClosed === true,
        temporarilyClosed: row.temporarilyClosed === true,
        scrapedAt: row.scrapedAt || null,
        canonical_lead_key: canonicalLeadKey,
        contact_availability: {
          has_email: Boolean(email),
          has_phone: Boolean(phone),
          has_website: Boolean(normalizedWebsite.website)
        }
      },
      stats: {
        raw_result_count: rows.length,
        normalized_count: 0,
        rejected_count: rejected,
        internal_duplicate_count: internalDuplicates,
        requested_leads: requested
      }
    }
  });
}

for (let index = 0; index < output.length; index++) {
  const item = output[index];
  item.json.is_recommended = index < 2;
  item.json.recommendation_rank = index < 2 ? index + 1 : null;
  item.json.stats.normalized_count = output.length;
  item.json.stats.rejected_count = rejected;
  item.json.stats.internal_duplicate_count = internalDuplicates;
}

if (!output.length) {
  return [{
    json: {
      candidate_present: false,
      job_id: context.job_id,
      collection_poll_worker_id: context.collection_poll_worker_id,
      requested_leads: requested,
      service_interest: context.service_interest,
      stats: {
        raw_result_count: rows.length,
        normalized_count: 0,
        rejected_count: rejected,
        internal_duplicate_count: internalDuplicates,
        requested_leads: requested
      }
    }
  }];
}
return output;

const candidate = $('Loop Over Candidates').first().json;
const saved = $json || {};
const message = [
  saved.error?.message,
  saved.error?.description,
  saved.errorMessage,
  saved.message,
  saved.description,
  saved.code
].filter(Boolean).join(' | ');
const serialized = `${message} ${JSON.stringify(saved.error || {})}`.toLowerCase();
const duplicate = serialized.includes('23505') || serialized.includes('duplicate') || serialized.includes('unique constraint');
const hasError = Boolean(
  saved.error ||
  saved.errorMessage ||
  (saved.httpCode && Number(saved.httpCode) >= 400) ||
  (saved.code && String(saved.code).toLowerCase().startsWith('pgrst')) ||
  duplicate
);
return {
  json: {
    ...candidate,
    candidate_saved: !hasError && Boolean(saved.id || saved.lead_key),
    candidate_duplicate: duplicate,
    candidate_save_error: hasError && !duplicate ? message.slice(0, 1500) : ''
  }
};

const outcomes = $input.all().map((item) => item.json || {});
const first = outcomes[0] || {};
const stats = first.stats || {};
const savedCount = outcomes.filter((item) => item.candidate_saved).length;
const recommendedCount = outcomes.filter((item) => item.candidate_saved && item.is_recommended).length;
const databaseDuplicates = outcomes.filter((item) => item.candidate_duplicate).length;
const databaseErrors = outcomes.filter((item) => item.candidate_save_error).length;
const duplicateCount = Number(stats.internal_duplicate_count || 0) + databaseDuplicates;
const rejectedCount = Number(stats.rejected_count || 0) + databaseErrors;
const requested = Number(stats.requested_leads || first.requested_leads || 0);
const finishedAt = new Date().toISOString();
const hasReviewableLeads = savedCount > 0;
return {
  json: {
    job_id: first.job_id,
    collection_poll_worker_id: first.collection_poll_worker_id,
    final_status: hasReviewableLeads ? 'needs_review' : 'completed_no_new_leads',
    current_stage: hasReviewableLeads ? 'human_review_ready' : 'lead_list_ready',
    progress_percent: 100,
    businesses_found: Number(stats.raw_result_count || 0),
    verified_leads: savedCount,
    duplicates_removed: duplicateCount,
    rejected_leads: rejectedCount,
    next_workflow: null,
    apify_finished_at: finishedAt,
    completed_at: finishedAt,
    result_summary: {
      requested_leads: requested,
      businesses_found: Number(stats.raw_result_count || 0),
      normalized_candidates: Number(stats.normalized_count || 0),
      discovery_candidates_saved: savedCount,
      available_for_review: savedCount,
      recommended_leads: recommendedCount,
      duplicates_removed: duplicateCount,
      rejected_leads: rejectedCount,
      candidate_database_errors: databaseErrors,
      intake_dispatch_status: hasReviewableLeads ? 'human_review_ready' : 'nothing_to_review'
    }
  }
};

const input = $json || {};
const stats = input.stats || {};
const finishedAt = new Date().toISOString();
return {
  json: {
    job_id: input.job_id,
    collection_poll_worker_id: input.collection_poll_worker_id,
    final_status: 'completed_no_new_leads',
    current_stage: 'lead_list_ready',
    progress_percent: 100,
    businesses_found: Number(stats.raw_result_count || 0),
    verified_leads: 0,
    duplicates_removed: Number(stats.internal_duplicate_count || 0),
    rejected_leads: Number(stats.rejected_count || 0),
    next_workflow: null,
    apify_finished_at: finishedAt,
    completed_at: finishedAt,
    result_summary: {
      requested_leads: Number(stats.requested_leads || input.requested_leads || 0),
      businesses_found: Number(stats.raw_result_count || 0),
      normalized_candidates: 0,
      discovery_candidates_saved: 0,
      available_for_review: 0,
      recommended_leads: 0,
      duplicates_removed: Number(stats.internal_duplicate_count || 0),
      rejected_leads: Number(stats.rejected_count || 0),
      candidate_database_errors: 0,
      intake_dispatch_status: 'nothing_to_review'
    }
  }
};

const job = $json || {};
const summary = job.result_summary || {};
const savedCount = Number(summary.discovery_candidates_saved || job.verified_leads || 0);
const foundCount = Number(summary.businesses_found || job.businesses_found || 0);
return {
  json: {
    job_id: job.job_id,
    event_type: 'lead_discovery_completed',
    status: job.status || 'completed',
    stage: job.current_stage || 'human_review_ready',
    severity: savedCount > 0 || foundCount === 0 ? 'info' : 'warning',
    error_code: job.error_code || '',
    event_message: 'Google Maps discovery finished: ' + savedCount + ' lead(s) available for human review from ' + foundCount + ' discovered business(es).',
    event_payload: summary
  }
};

const input = $json || {};
return {
  json: {
    job_id: input.job_id,
    collection_poll_worker_id: input.collection_poll_worker_id,
    dataset_fetch_error: input.dataset_fetch_error,
    event_type: 'dataset_fetch_retry',
    status: 'collecting',
    stage: 'fetching_google_maps_results',
    severity: 'warning',
    error_code: 'APIFY_DATASET_FETCH_FAILED',
    event_message: input.dataset_fetch_error || 'Apify dataset could not be fetched; next scheduler run will retry.',
    event_payload: {
      apify_run_id: input.apify_run_id,
      apify_dataset_id: input.apify_dataset_id
    }
  }
};

const candidate = $('Loop Pending Intake Leads').first().json;
const sheet = $json || {};
const message = [
  sheet.error?.message,
  sheet.error?.description,
  sheet.errorMessage,
  sheet.message,
  sheet.description
].filter(Boolean).join(' | ');
const hasError = Boolean(
  sheet.error ||
  sheet.errorMessage ||
  (sheet.httpCode && Number(sheet.httpCode) >= 400)
);
return {
  json: {
    ...candidate,
    sheet_sync_ok: !hasError,
    sheet_sync_attempts_next: Number(candidate.sheet_sync_attempts || 0) + 1,
    intake_status_next: hasError ? 'website_verified' : 'sent_to_intake',
    sheet_sync_error: hasError ? message.slice(0, 1500) : '',
    sheet_synced_at: hasError ? null : new Date().toISOString()
  }
};

const cutoff = Date.now() - 10 * 60 * 1000;
return $input.all().filter((item) => {
  const row = item.json || {};
  const timestamp = Date.parse(row.locked_at || row.updated_at || '');
  return row.id && row.status === 'collection_polling' && Number.isFinite(timestamp) && timestamp < cutoff;
}).slice(0, 1).map((item) => ({ json: { ...item.json, stale_poll_status: item.json.status, stale_poll_worker_id: item.json.locked_by } }));
